import type { PrepareAgentRequest, TranscribeResponse } from "@/types/api";

const API_URL = process.env.NEXT_PUBLIC_API_URL!;
const STT_URL = process.env.NEXT_PUBLIC_STT_URL!;

export async function prepareAgent(data: PrepareAgentRequest): Promise<void> {
  await fetch(`${API_URL}/api/conversation/prepare-agent`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(data),
  });
}

export async function resetAgent(): Promise<void> {
  await fetch(`${API_URL}/api/conversation/reset-agent`, { method: "POST" });
}

export function streamConverse(message: string): Promise<Response> {
  return fetch(`${API_URL}/api/conversation/converse/stream`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ message }),
  });
}

export async function transcribeAudio(
  audioBlob: Blob,
): Promise<TranscribeResponse> {
  const formData = new FormData();
  formData.append("file", audioBlob, "audio.webm");
  const res = await fetch(`${STT_URL}/transcribe`, {
    method: "POST",
    body: formData,
  });
  return res.json();
}
